fn main() {
    // ---- &str (string slice) ----
    // Borrowed, immutable, fast, fixed
    let greeting: &str = "Hello, Hero!";
    let name: &str = "Aragorn";

    println!("Greeting: {}", greeting);
    println!("Name: {}", name);

    // ---- String (heap-allocated) ----
    // Owned, mutable, growable, slower
    let mut message = String::from("Welcome to");
    message.push_str(" Rust!");
    message.push(' ');
    message.push_str("Let's fight.");

    println!("Message: {}", message);

    // ---- Converting &str to String ----
    let slice: &str = "Hello";
    let string: String = slice.to_string();
    let string2: String = String::from(slice);

    // ---- Converting String to &str ----
    let s = String::from("World");
    let slice2: &str = &s;  // Coercion
    let slice3: &str = &s[..];  // Explicit

    println!("String: {}", s);
    println!("Slice: {}", slice2);

    // ---- Modifying String ----
    let mut score_msg = String::from("Score: ");
    score_msg.push_str(&100.to_string());  // Convert number to string
    println!("{}", score_msg);

    // ---- String concatenation ----
    let hello = String::from("Hello");
    let world = String::from("World");
    let combined = hello + " " + &world;  // hello is moved!
    println!("Combined: {}", combined);
}

