fn main() {
    let name: &str = "Hero";
    let mut level_msg = String::from("Level: ");
    level_msg.push_str(&5.to_string());

    println!("Name: {}", name);
    println!("{}", level_msg);

    let name_string = name.to_string();
    let ready = name_string + " is ready";
    println!("{}", ready);
}
